INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT105-S2-Q8$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Each mother bat can recognize her own pup's call.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$Mothers are reunited with their pups quickly. Calls are the bats' only way to find each other. Pups cannot tell their mother's call from any other adult's.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Someone is doing the recognizing. There are only two candidates: the pup finds the mother, or the mother finds the pup. The author rules out the pup (it cannot tell its mother's call from the rest), which leaves the mother. That is eliminating the alternative explanation.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Supporting one explanation by ruling out the other.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT105-S2-Q8$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Students pick this because the conclusion is about "each" mother. But the argument does not study a sample and generalize. It reasons about how the reunion could work at all.$batch05$), ($batch05$B$batch05$, $batch05$The phenomenon is the quick reunion. The explanation that survives is "the mother recognizes the pup's call." The one excluded is "the pup recognizes the mother."$batch05$), ($batch05$C$batch05$, $batch05$This is the most popular wrong answer. Recognizing a call sounds like a mechanism. But the author never describes *how* recognition works. They establish *who* does it by elimination. "Can occur" also misses: the author takes for granted that reunions happen and asks how.$batch05$), ($batch05$D$batch05$, $batch05$No two groups are compared.$batch05$), ($batch05$E$batch05$, $batch05$No general rule is applied to a case.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT105-S2-Q8$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
